      "text": "صَنْعَاءُ: بالفتح ثم السكون وألف ممدودة، أعظم مدن اليمن وقصبتها وأقدمها عمارة، يقال ما بنى الآدميون بعد بابل أقدم من صنعاء، وهي حسنة البناء طيبة الهواء والماء، قالوا: لا بد من صنعاء وإن طال السفر."
